sp_widget.client_script:
api.controller = function($http, spUtil) {
  var c = this;
  c.selectedFile = null;
  c.profileSysId = '';
  c.uploading = false;
  c.parseStatus = '';
  c.parseError = '';
  c.parseAttempts = 0;
  c.skills = [];
  c.tools = [];

  c.loadProfile = function() {
    return c.server.get({ action: 'get_profile' }).then(function(response) {
      var result = (response && response.data) || {};
      c.parseStatus = result.parse_status || '';
      c.parseError = result.parse_error || '';
      c.parseAttempts = result.parse_attempts || 0;
      c.skills = result.skills || [];
      c.tools = result.tools || [];
      if (!result.profile_sys_id) {
        if (result.error)
          spUtil.addErrorMessage(result.error);
        return;
      }
      c.profileSysId = result.profile_sys_id;
    });
  };

  c.loadProfile();

  c.onFileSelected = function(files) {
    c.selectedFile = (files && files[0]) || null;
  };

  c.uploadResume = function() {
    if (!c.selectedFile || !c.profileSysId)
      return;

    var file = c.selectedFile;
    var fileName = (file.name || '').toLowerCase();
    var fileType = (file.type || '').toLowerCase();

    if (fileType && fileType !== 'application/pdf') {
      spUtil.addErrorMessage('Only PDF resumes are supported.');
      return;
    }
    if (fileName.slice(-4) !== '.pdf') {
      spUtil.addErrorMessage('Only PDF resumes are supported.');
      return;
    }

    c.uploading = true;
    var url = '/api/now/attachment/file' +
      '?table_name=x_2311790_skills_0_student_profile' +
      '&table_sys_id=' + encodeURIComponent(c.profileSysId) +
      '&file_name=' + encodeURIComponent(file.name);

    $http.post(url, file, {
      headers: {
        'Content-Type': 'application/pdf',
        'X-UserToken': window.g_ck
      },
      transformRequest: []
    }).then(function() {
      c.uploading = false;
      c.selectedFile = null;
      spUtil.addInfoMessage('Resume attached. Parsing has started.');
      return c.loadProfile();
    }, function(err) {
      c.uploading = false;
      var msg = (err && err.data && err.data.error && err.data.error.message) ||
        'Upload failed. Check attachment permissions on the student profile table.';
      spUtil.addErrorMessage(msg);
    });
  };
};

sp_widget.css:
.skillsync-container {
  max-width: 620px;
  margin: 24px auto;
  padding: 32px;
  background: #fff;
  border: 1px solid #d8e2e8;
  border-radius: 12px;
  box-shadow: 0 4px 14px rgba(17, 75, 95, 0.08);
  text-align: center;
}

.skillsync-title {
  margin: 0 0 8px;
  color: #114b5f;
  font-size: 22px;
  font-weight: 700;
}

.skillsync-text,
.skillsync-note {
  color: #52666d;
}

.skillsync-note {
  margin: 14px 0 0;
  font-size: 13px;
}

.skillsync-status {
  margin: 16px 0 0;
  font-weight: 600;
}

.skillsync-status-pending { color: #9a6700; }
.skillsync-status-parsed { color: #1b7f3a; }
.skillsync-status-failed { color: #b32020; }

.skillsync-error {
  margin: 8px 0 0;
  color: #b32020;
  font-size: 13px;
  word-break: break-word;
}

.skillsync-parsed {
  margin-top: 18px;
  text-align: left;
}

.skillsync-parsed h4 {
  margin: 12px 0 6px;
  color: #114b5f;
  font-size: 14px;
}

.skillsync-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.skillsync-chip {
  display: inline-block;
  padding: 4px 9px;
  border: 1px solid #c8d8de;
  border-radius: 999px;
  background: #f4f8fa;
  color: #264e5c;
  font-size: 12px;
}

.skillsync-chip-core {
  border-color: #1b7f3a;
  background: #e8f5ec;
  color: #1b7f3a;
}

sp_widget.script:
(function() {
  data.table = 'x_2311790_skills_0_student_profile';
  data.profile_sys_id = '';
  data.parse_status = '';
  data.parse_error = '';
  data.parse_attempts = 0;
  data.skills = [];
  data.tools = [];
  data.error = '';

  if (!gs.isLoggedIn()) {
    data.error = 'Sign in to upload a resume.';
    return;
  }

  if (!gs.hasRole('x_2311790_skills_0.student') && !gs.hasRole('x_2311790_skills_0.student_profile_user')) {
    data.error = 'Your account is not allowed to upload resumes.';
    return;
  }

  var userId = gs.getUserID();
  var profile = new GlideRecord(data.table);
  profile.addQuery('u_user', userId);
  profile.setLimit(1);
  profile.query();

  if (profile.next()) {
    data.profile_sys_id = profile.getUniqueValue();
    data.parse_status = profile.getValue('u_parse_status') || '';
    data.parse_error = profile.getValue('u_parse_error') || '';
    data.parse_attempts = profile.getValue('u_parse_attempts') || '0';

    var skillGr = new GlideRecord('x_2311790_skills_0_student_skill');
    skillGr.addQuery('u_profile', data.profile_sys_id);
    skillGr.addQuery('u_source', 'resume');
    skillGr.orderBy('u_rank');
    skillGr.query();

    while (skillGr.next()) {
      var masterSysId = skillGr.getValue('u_skill');
      var name = '';
      var master = new GlideRecord('x_2311790_skills_0_skill_master');
      if (masterSysId && master.get(masterSysId))
        name = master.getValue('name');
      if (!name)
        name = skillGr.getDisplayValue('u_skill');

      var row = {
        name: name,
        rank: skillGr.getValue('u_rank') || '',
        proficiency: skillGr.getValue('u_proficiency') || '',
        core: skillGr.getValue('u_core') == 'true' || skillGr.getValue('u_core') == '1'
      };

      if (skillGr.getValue('u_skill_type') == 'tool')
        data.tools.push(row);
      else
        data.skills.push(row);
    }
  } else {
    data.error = 'No student profile was found for your account. Ask an administrator to create one.';
  }
})();
